const lines=[],groups={};let active=null;
const log=(...args)=>lines.push(args.join(' '));
function test(label,callback){if(CASE&&CASE!==label)return;const start=lines.length;try{callback()}catch(e){log(label,'ERROR',e.name,e.message)}finally{if(active)active.remove();active=null}groups[label]=lines.slice(start)}
function create(type,attrs={}){const i=document.createElement('input');for(const [k,v]of Object.entries(attrs))i.setAttribute(k,v);i.type=type;return i}
function sample(label,type,values,attrs={}){const i=create(type,attrs);for(const value of values){i.value=value;log(label,JSON.stringify([value,i.value]))}}
function mount(html){active=document.createElement('div');active.innerHTML=html;document.body.append(active);return active}
test('number-values',()=>sample('number-values','number',['','bad','0','-0','+1','01','1.','1.0','.5','-.5','1e2','1E+2','1e','1e309','1e-400',' 1','1 ','0x10','Infinity','NaN','1_000','--1','1\n2']));
test('number-constraints',()=>sample('number-constraints','number',['-1','0','0.5','5','10','11'],{min:'0',max:'10',step:'2'}));
test('range-values',()=>sample('range-values','range',['','bad','-1','0','0.5','1','49.4','49.5','50.5','99.7','100','101','1e309']));
test('range-fractions',()=>sample('range-fractions','range',['','0.05','0.15','0.25','0.35','0.99','-1','1.2'],{min:'0',max:'1',step:'0.1'}));
test('range-base',()=>sample('range-base','range',['','1','2','4','5','6','8','10','11'],{min:'1',max:'10',step:'3'}));
test('range-any',()=>sample('range-any','range',['','bad','0.125','-1','2','1e-20'],{min:'0',max:'1',step:'any'}));
test('range-initial',()=>{for(const markup of ['<input type=range>','<input type=range max=200>','<input max=200 type=range>','<input type=range min=10 max=20>','<input min=10 max=20 type=range>','<input value=50 type=range min=0 max=100 step=20>','<input type=range value=10 min=5 max=15 step=3>','<input type=range min=10 max=5>','<input type=range min=0 max=1 step=2>']){const b=mount(markup);log('range-initial',markup,b.querySelector('input').value);b.remove();active=null}});
test('range-attribute-numbers',()=>{for(const attr of ['+2',' 2','2junk','0x2','1.5','Infinity','1e309','-3']){const i=create('range',{min:attr,max:'10'});i.value='-100';log('range-attribute-numbers',JSON.stringify([attr,i.value]))}});
test('range-step-values',()=>{for(const step of ['0','-1','bad','ANY','0.2junk',' 0.2','+0.2','1e-1']){const i=create('range',{min:'0',max:'1',step});i.value='0.35';log('range-step-values',JSON.stringify([step,i.value]))}});
test('range-dynamic',()=>{const i=create('range');log('range-dynamic','initial',i.value);i.setAttribute('max','200');log('range-dynamic','max',i.value);i.value='150';i.setAttribute('max','100');log('range-dynamic','clamp',i.value);i.setAttribute('min','80');i.setAttribute('step','30');log('range-dynamic','step',i.value);i.setAttribute('value','91');log('range-dynamic','value-attr',i.value,i.defaultValue)});
test('range-base-attribute',()=>{const i=create('range',{value:'0.2',max:'1',step:'0.3'});i.value='0.75';log('range-base-attribute','before',i.value);i.setAttribute('value','0.1');log('range-base-attribute','after',i.value,i.defaultValue);i.value='0.75';log('range-base-attribute','set',i.value)});
test('date-values',()=>sample('date-values','date',['','bad','2024-02-29','2023-02-29','2000-02-29','1900-02-29','2024-2-01','2024-01-1','0000-01-01','0001-01-01','00001-01-01','99999-12-31','275760-09-13','275760-09-14','999999999999-01-01','2024-13-01','2024-04-31','2024-01-01Z']));
test('month-values',()=>sample('month-values','month',['','bad','2024-02','2024-2','0000-01','0001-01','00001-01','99999-12','2024-00','2024-13','2024-02-01']));
test('week-values',()=>sample('week-values','week',['','bad','2020-W53','2021-W53','2015-W53','2009-W53','2024-W01','2024-W00','2024-W54','2024-W1','0001-W01','0000-W01','00001-W01','2024-w01']));
test('time-values',()=>sample('time-values','time',['','bad','00:00','23:59','24:00','12:34:56','12:34:60','12:34:56.1','12:34:56.120','12:34:56.1234','1:02','12:3','12:34Z','12:34:00.000','12:34.5']));
test('datetime-values',()=>sample('datetime-values','datetime-local',['','bad','2024-02-29T12:34','2024-02-29 12:34','2024-02-29T12:34:00','2024-02-29T12:34:00.100','2024-02-29T12:34:56.120','2023-02-29T12:34','2024-01-01T24:00','2024-01-01t12:34','2024-01-01T12:34Z','00001-01-01T00:00']));
test('typed-parse-order',()=>{for(const [type,value]of [['number','bad'],['range','bad'],['date','2024-02-29'],['date','bad'],['time','12:34:56.120'],['datetime-local','2024-02-29 12:34:00.100']])for(const order of [false,true]){const markup=order?'<input value="'+value+'" type="'+type+'">':'<input type="'+type+'" value="'+value+'">';const b=mount(markup);log('typed-parse-order',JSON.stringify([type,value,order,b.querySelector('input').value]));b.remove();active=null}});
test('typed-defaults',()=>{for(const type of ['number','range','date','month','week','time','datetime-local']){const i=create(type);i.defaultValue='bad';log('typed-defaults',type,i.value,i.defaultValue)}});
test('range-decimals',()=>{for(const [attrs,value]of [[{min:'-1',max:'1',step:'.1'},'-.15'],[{min:'-.35',max:'.35',step:'.1'},'0'],[{min:'0',max:'1',step:'.3'},'.99'],[{value:'.2',min:'bad',max:'.25',step:'.3'},'.1'],[{value:'1',max:'.5',step:'2'},'.25'],[{min:'-1e308',max:'1e308',step:'any'},''],[{min:'1e308',max:'1.7e308',step:'any'},''],[{min:'0',max:'1e-300',step:'1e-301'},'1.5e-301'],[{min:'0',max:'1',step:'1e-320'},'.123'],[{min:'-100',max:'100',step:'2'},'-3'],[{min:'0',max:'1',step:'.1'},'0.30000000000000004']]){const i=create('range',attrs);i.value=value;log('range-decimals',JSON.stringify([attrs,value,i.value]))}});
test('range-reflection',()=>{const i=create('range');for(const [k,v]of [['min','10'],['max','20'],['step','3']]){i[k]=v;log('range-reflection',k,i[k],i.getAttribute(k),i.value)}i.value='17';i.min='16';log('range-reflection','changed',i.value);i.removeAttribute('min');log('range-reflection','removed',i.min,i.value);let conversions=0;i.min={toString(){conversions++;return '3'}};log('range-reflection','coerced',conversions,i.value);for(const k of ['min','max','step']){const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,k);try{d.get.call({});log('range-reflection','unbranded',k)}catch(e){log('range-reflection','brand',k,e.name)}}});
test('domain-copies-reset',()=>{const b=mount('<form><input name=n type=number value=bad><input name=r type=range min=1 max=10 step=3 value=8><input name=d type=date value=2023-02-29><input name=t type=datetime-local value="2024-02-29 12:34:00.100"></form>'),f=b.firstChild;for(const i of f.querySelectorAll('input')){log('domain-copies-reset','initial',i.name,i.value,i.defaultValue);i.value=i.name==='r'?'5':'bad';const copy=i.cloneNode();log('domain-copies-reset','copy',i.name,i.value,copy.value,copy.defaultValue)}log('domain-copies-reset','data',JSON.stringify([...new FormData(f)]));f.reset();log('domain-copies-reset','reset',JSON.stringify([...new FormData(f)]))});
test('domain-type-changes',()=>{for(const [before,after,value]of [['text','number','bad'],['text','number','1e2'],['text','range','2.5'],['number','text','bad'],['range','text','bad'],['text','date','2023-02-29'],['text','week','2021-W53'],['text','datetime-local','2024-02-29 12:34:00.100']]){const i=create(before);i.value=value;i.type=after;log('domain-type-changes',JSON.stringify([before,after,value,i.value,i.defaultValue]))}});
test('domain-intrinsics',()=>{const number=Number,bigint=BigInt,string=String,sp=String.prototype,ex=RegExp.prototype.exec,sl=String.prototype.slice,fl=Math.floor,mn=Math.min;let calls=0;const poison=()=>{calls++;throw Error('author replacement')};try{globalThis.Number=poison;globalThis.BigInt=poison;globalThis.String=poison;RegExp.prototype.exec=poison;sp.slice=poison;Math.floor=poison;Math.min=poison;const n=create('number');n.value='bad';const r=create('range',{min:'-1',max:'1',step:'.1'});r.value='-.15';const w=create('week');w.value='2021-W53';const d=create('datetime-local');d.value='2024-02-29 12:34:00.100';log('domain-intrinsics',JSON.stringify([n.value,r.value,w.value,d.value,calls]))}finally{globalThis.Number=number;globalThis.BigInt=bigint;globalThis.String=string;RegExp.prototype.exec=ex;sp.slice=sl;Math.floor=fl;Math.min=mn}});
test('week-year-matrix',()=>{const i=create('week');for(let start=1;start<=400;start+=80){let bits='';for(let y=start;y<start+80;y++){i.value=String(y).padStart(4,'0')+'-W53';bits+=i.value?'1':'0'}log('week-year-matrix',start,bits)}});
test('domain-line-endings',()=>{for(const [type,value]of [['number','1\n'],['number','1\r'],['number','１'],['number','1\u00a0'],['range','1\n'],['date','2024-01-01\n'],['month','2024-01\n'],['week','2024-W01\n'],['time','12:00\n'],['datetime-local','2024-01-01T12:00\n']]){const i=create(type);i.value=value;log('domain-line-endings',JSON.stringify([type,value,i.value]))}});
